Method.Implementation:
Set tStatus = $$$OK
Try {
// Run for all namespaces Set tStatus = ..GetEnvironment(.tEnvironment,.tInstanceType,.tInstanceName) $$$ThrowOnError(tStatus)
// Create the JSON container stream Set pJSONStream = ##class(%Stream.GlobalCharacter).%New() Do pJSONStream.Write("[")
// Loop through namespace list Set tQuery = "SELECT DISTINCT Namespace FROM IHC_EAI_System_Data.Namespace WHERE EnvironmentType = ? AND InstanceName = ?" Set tStatement = ##class(%SQL.Statement).%New() Set tStatus = tStatement.%Prepare(tQuery) $$$ThrowOnError(tStatus) Set tResultSet = tStatement.%Execute(tEnvironment,tInstanceName)
Set tIsFirst = 1 While (tResultSet.%Next(.tStatus)) { $$$ThrowOnError(tStatus)
Set tNamespace = tResultSet.%GetData(1)
Set tJSONObj = ""
Do:'(tIsFirst) pJSONStream.Write(",")
// Create the snapshot per namespace If (pCountType = "") { Set tInJSONObj = ..CreateSnapshot(tNamespace,"Total",pCountDate,pDebug,.tStatus) $$$ThrowOnError(tStatus) Set tStatus = ..ObjectToJSONStream(tInJSONObj,.tInJSONObjStream,"aiw") $$$ThrowOnError(tStatus) Do pJSONStream.CopyFrom(tInJSONObjStream)
Do pJSONStream.Write(",")
Set tOutJSONObj = ..CreateSnapshot(tNamespace,"Enabled",pCountDate,pDebug,.tStatus) $$$ThrowOnError(tStatus) Set tStatus = ..ObjectToJSONStream(tOutJSONObj,.tOutJSONObjStream,"aiw") $$$ThrowOnError(tStatus) Do pJSONStream.CopyFrom(tOutJSONObjStream)
Do pJSONStream.Write(",")
Set tOutJSONObj = ..CreateSnapshot(tNamespace,"Disabled",pCountDate,pDebug,.tStatus) $$$ThrowOnError(tStatus) Set tStatus = ..ObjectToJSONStream(tOutJSONObj,.tOutJSONObjStream,"aiw") $$$ThrowOnError(tStatus) Do pJSONStream.CopyFrom(tOutJSONObjStream)
} Else { Do:('tIsFirst) pJSONStream.Write(",")
// Write JSON out to array stream Set tJSONObj = ..CreateSnapshot(tNamespace,pCountType,pCountDate,pDebug,.tStatus) $$$ThrowOnError(tStatus) Set tStatus = ..ObjectToJSONStream(tJSONObj,.tJSONObjStream,"aiw") $$$ThrowOnError(tStatus) Do pJSONStream.CopyFrom(tJSONObjStream) }
Set:(tIsFirst) tIsFirst = 0 } $$$ThrowOnError(tStatus)
Do pJSONStream.Write("]")
If (pSendSnapshots) { // Send all snapshots to the business service Set tStatus = ..SendSnapshot(pJSONStream) $$$ThrowOnError(tStatus) }
} Catch eException { Set tStatus = eException.AsStatus() } Quit tStatus

	Set tSnapshotJSON = ""
	Try {
		New $NAMESPACE
		Set $NAMESPACE = pNamespace
		
		Kill:(pDebug) ^EAI.Debug.TransactionCount
		
		Set tCurrentDatetime = $ZDATETIME($H,3)
		
		Set tSnapshotJSON = ..CreateSnapshotJSON(pCountType,pCountDate,tCurrentDatetime,pDebug,.pStatus)
		$$$ThrowOnError(pStatus)

	} Catch eException {
		Set pStatus = eException.AsStatus()
	}
	Quit tSnapshotJSON

Set tSnapshotJSON = ""

Try {
	Set tSnapshotJSON = ##class(IHC.EAI.KPI.JSON.ComponentCount).%New()
	Set tSnapshotJSON.createdOn = pCurrentDatetime
	Set tSnapshotJSON.application = "Ensemble"
	Set tSnapshotJSON.group = $NAMESPACE
	Set tSnapshotJSON.valueDate = $ZD(pCountDate,3)
	Set tSnapshotJSON.type = pCountType
	
	// Component counts
	Set tSnapshotJSON.value = ..GetComponentCount(pCountType,.tStatus)
	$$$ThrowOnError(tStatus)
	
	Set:(pDebug) ^EAI.Debug.ComponentCount($NAMESPACE,pCountDate,pCountType,"Value") = tSnapshotJSON.value
	
} Catch eException {
	Set pStatus = eException.AsStatus()
}
Quit tSnapshotJSON

Set tCount = 0
Try {
	Set SQLCODE = ""
	If (pCountType = "Enabled") {
		&sql(SELECT COUNT(%Id) INTO :tCount FROM Ens_Config.Item WHERE Enabled = 1)
	} ElseIf (pCountType = "Disabled") {
		&sql(SELECT COUNT(%Id) INTO :tCount FROM Ens_Config.Item WHERE Enabled = 0)
	} Else {
		&sql(SELECT COUNT(%Id) INTO :tCount FROM Ens_Config.Item)
	}
	If (SQLCODE '= 0) {
		$$$ThrowStatus($$$ERROR($$$SQLError, "Component Count query failed. pEnabled:" _ pEnabled))	
	}
} Catch eException {
	Set pStatus = eException.AsStatus()
}
Quit tCount
